'use strict';
const assert=require('node:assert/strict');
const {createLibraVmHarness}=require('./libra_vm_harness.cjs');
const CORE=['runTurnPlanner','runSgaPipeline','loadSettings','buildSgaPatchBinding','normalizeBoundSgaPatch','consumerEntityProjection','packSgaEvidenceJsonForPrompt','buildSgaAidePrompts','sgaRouteIdentityFor','buildDraftPatchDocument','prepareConsumerEvidence','assertConsumerReadSet','assertConsumerEvidenceCurrent','buildInputWriterDeliverySnapshot'];
function instrument(source){
 const n='      debugApplyDraftPatchOperations: (draftValue, edits = []) =>';assert.equal(source.split(n).length,2);
 source=source.replace(n,`      consumerTestInternals:{${CORE.join(',')}},\n${n}`);
 const n2="    debugSgaPatchOperations(draft = '', edits = [])";assert.equal(source.split(n2).length,2);
 return source.replace(n2,`    consumerTestInternals(){return LibraMemoryCore.consumerTestInternals;},\n${n2}`);
}
const sample='민아는 금고를 열어 달라는 지호의 요청을 듣고도 고개를 저었다. 암호를 알려 주겠다고 약속한 적이 없었고, 지금도 그 생각에는 변함이 없었다. 그녀는 책상 위에 놓인 열쇠를 손으로 덮은 채, 왜 그것이 필요한지 먼저 설명해 달라고 말했다. 지호가 답할 시간을 주기 위해 잠시 말을 멈추었다. 창문으로 들어온 바람에 종이 한 장이 흔들렸지만 두 사람은 서재를 떠나지 않았다.';
function hostData(){const chat={id:'consumer-chat',chatId:'consumer-chat',message:[{role:'user',data:'서재에 들어간다.',chatId:'u1'},{role:'assistant',data:sample,chatId:'a1'}],bindedPersona:'',note:'NOTE_BEFORE 암호를 공개하지 말 것'};chat.messages=chat.message;const character={id:'consumer-character',chaId:'consumer-character',name:'민아',desc:'민아는 서재를 관리한다. DESC_BEFORE',chatPage:0,chats:[chat]};const db={personas:[],selectedPersona:'',characters:[character],plugins:[],modules:[],enabledModules:[]};return {chat,character,db,host:{async getCurrentCharacterIndex(){return 0},async getCurrentChatIndex(){return 0},async getCharacter(){return character},async getCharacterFromIndex(){return character},async getChatFromIndex(){return chat},async getDatabase(fields){return Object.fromEntries(fields.map(k=>[k,db[k]??null]));}}};}
const shadow=(draft=sample)=>({schema:'libra.sga_shadow.v2',ok:true,continuity_locks:['암호를 지호에게 공개하지 않는다.'],user_agency_locks:['지호의 다음 선택은 사용자에게 남긴다.'],do_not_reveal:[],scene_design:{purpose:'요청에 대한 반응',primary_tension:'암호 공개 여부',beats:['민아가 설명을 요구함'],ending_boundary:'지호의 답을 기다림'},draft});
function bindingFromPrompt(options){const u=(options.messages||[]).filter(m=>m.role==='user').map(m=>m.content).join('\n');const m=u.match(/\[REQUEST PATCH BINDING[^\n]*\]\n([^\n]+)/);return m?JSON.parse(m[1]):null;}
function boundPatch(options,edits=[]){const b=bindingFromPrompt(options);assert.ok(b,'actual v3 binding absent from provider prompt');return {schema:'libra.sga_patch.v3',stage:b.stage,ok:true,analysis:{summary:'담당 영역에서 필요한 부분을 확인했다.',constraints:[],risks:[]},continuity_locks:[],user_agency_locks:[],do_not_reveal:[],edits,binding:{schema:b.schema,token:b.token},edit_links:edits.map((_,index)=>({editIndex:index,domain:b.domain,entityRefs:[],evidenceRefs:['source_input'],constraintRefs:[],effects:[]}))};}
const choices=(mode='rp')=>({schema:'libra.input_writer_choices.v1',ok:true,mode,choices:[{id:'A',title:'질문',summary:'이유를 묻는다.',perspective:mode==='author'?'user_focus':'',input:'민아에게 금고를 닫아 둔 이유를 물어본다.'},{id:'B',title:'관찰',summary:'반응을 기다린다.',perspective:mode==='author'?'npc_focus':'',input:'문에서 한 걸음 떨어져 민아의 반응을 기다린다.'},{id:'C',title:'제안',summary:'서두르지 않는다.',perspective:mode==='author'?'offscreen_focus':'',input:'서두르지 않아도 된다고 말하고 의자에 앉는다.'}]});
function evidence(){return {current_input:'민아에게 금고를 열어 달라고 부탁한다.',terminal_scene:sample,layers:{memory:[],entity:[],world:[],narrative:[]},source_summary:{selected_memories:0},author_note_prompt:'AUTHOR_NOTE_SENTINEL 암호를 공개하지 않는다.',continuity_state_prompt:'민아는 암호를 알고 지호는 모른다.',live_tail_prompt:'두 사람은 현재 서재에 있다.',narrative_state:null,narrative_direction:null};}
function generated(options){const all=(options.messages||[]).map(m=>m.content).join('\n');if(all.includes('Return the bounded private analysis JSON now.')){const m=all.match(/"schema":"([^"]+)","stage":"([^"]+)"/);return {schema:m[1],stage:m[2],ok:true,summary:'현재 단계의 제약을 검토했다.',constraints:[],risks:[],directives:[]};}if(bindingFromPrompt(options))return boundPatch(options);if(all.includes('LOCKED LIBRA INPUT WRITER CONTRACT'))return choices(all.includes('"mode":"author"')?'author':'rp');return shadow();}
async function withHarness(args,fn,onCall){const data=hostData(),calls=[];const h=await createLibraVmHarness({enable_gui:'false',bootstrap_references_enabled:'false',input_writer_enabled:'true',input_writer_mode:'rp',...args},{...data.host,async runLLMModel(options){calls.push(structuredClone(options));const out=onCall?await onCall(options,calls.length,data):generated(options);return out?.type?out:{type:'success',result:typeof out==='string'?out:JSON.stringify(out),usage:{prompt_tokens:100,completion_tokens:20,total_tokens:120}};}},{transformSource:instrument});try{return await fn(h,data,calls,h.api.consumerTestInternals());}finally{await h.cleanup();}}
module.exports={assert,withHarness,evidence,choices,shadow,generated,boundPatch,bindingFromPrompt,hostData,sample,createLibraVmHarness,instrument};
